set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
root=/var/lib/news-flow/qc-close25-20261122
install -o news-flow -g news-flow -m 0600 "$upload_dir/.qc-close25-source-closeout.json" "$root/source-closeout.json"
install -o news-flow -g news-flow -m 0600 "$upload_dir/.qc-close25-report.txt" "$root/QC-REPORT.txt"
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';import {execFileSync} from 'node:child_process';import {DatabaseSync} from 'node:sqlite';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {collectDiscoveryHealth} from './src/newsFlow/discoveryHealth.mjs';const root='/var/lib/news-flow/qc-close25-20261122',sha=x=>createHash('sha256').update(x).digest('hex'),batch=JSON.parse(fs.readFileSync(root+'/batch.json')),closeout=JSON.parse(fs.readFileSync(root+'/source-closeout.json')),db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true});try{assert.equal(closeout.cases.length,25);assert.deepEqual([...closeout.cases.map(s=>s.site)].sort(),[...batch.cohort].sort());const r={at:new Date().toISOString(),configs:batch.sites.map(s=>({site:s.site,sha256:sha(fs.readFileSync(s.file)),unchanged:s.fileSha===sha(fs.readFileSync(s.file))})),aiLedgerUnchanged:JSON.stringify(batch.aiUsage)===JSON.stringify(db.prepare('SELECT * FROM ai_usage ORDER BY day').all()),services:execFileSync('systemctl',['show','news-flow-seed','news-flow-parse','news-flow-import','-p','Id,MainPID,ActiveState,NRestarts'],{encoding:'utf8'}),artifacts:Object.fromEntries(['source-closeout.json','QC-REPORT.txt'].map(n=>[n,sha(fs.readFileSync(root+'/'+n))])),runtimeCode:Object.fromEntries(['transport','state'].map(n=>[n,sha(fs.readFileSync('src/newsFlow/'+n+'.mjs'))]))};const registry=await loadNewsRegistry(),health=collectDiscoveryHealth(db,registry.sources.values());r.cohortAlerts=health.sites.filter(s=>batch.cohort.includes(s.site)).map(s=>({site:s.site,alerts:s.alerts}));assert(r.configs.every(s=>s.unchanged));assert(r.aiLedgerUnchanged);assert.equal((r.services.match(/ActiveState=active/g)||[]).length,3);assert.equal((r.services.match(/NRestarts=0/g)||[]).length,3);fs.writeFileSync(root+'/final-state.json',JSON.stringify(r,null,2));console.log(JSON.stringify(r));}finally{db.close();}
NODE
install -o "$SUDO_USER" -m 0600 "$root/final-state.json" "$upload_dir/.qc-close25-final-state.json"
tar -C "$root" -czf "$upload_dir/.qc-close25-evidence.tar.gz" evidence batch.json supplement.json payload-inspection.json source-closeout.json QC-REPORT.txt final-state.json
chown "$SUDO_USER" "$upload_dir/.qc-close25-evidence.tar.gz"
chmod 0600 "$upload_dir/.qc-close25-evidence.tar.gz"
